        "valueString": "decreased sleep with baby waking 2-3 times per night and racing thoughts"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Anxiety severity and frequency"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Marked anxiety related to baby's health with checking and reassurance seeking, 2-3 panic attacks per week lasting 10-15 minutes, self-resolving"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
